// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint56 _changeFee) public {
        vm.assume(_changeFee > 0);
        try c.initialize(
            address(0),
            address(0),
            1,
            1,
            _changeFee,
            0,
            bytes32(0),
            false,
            false
        ) {} catch {
            return;
        }
        assertTrue(c.changeFee() == _changeFee);
    }
}
